@startuml

class SensorController {
  + systemName : string
  + querySensorValues(inhabitant: string) : void
  + configureSensor(sensor: int) : void
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
  + isAdmin : boolean
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : string
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email: string) : void
}

SensorController "1" -- "1..*" Inhabitant
SensorController "1" -- "1" Apartment
SensorController "1" -- "1..*" Sensor
Inhabitant "1" -- "1..*" Sensor
Apartment "1" *-- "2..*" Room
Room "1" -- "1..*" Sensor
Sensor "1" -- "1..*" SensorValue
Sensor "1" -- "1" Unit
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
EMonitor ..> Sensor : checks
EMonitor ..> SensorController : sendsAlertVia

@enduml

